# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        span = Span(9 * 60 + 4, 17 * 60 + 10)
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_spans([Span(60, 125)], 10),
            ["01:00-02:10 (1h 10m)"],
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(600, 660)]
        self.assertEqual(len(round_spans(spans, 5)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
